"""Explicit editorial migration. Private source snapshots are required for anchors."""
import json, re
from pathlib import Path

root=Path('content/vestigium')
if (root/'editorial/guard-v3/progress.json').exists():
 raise SystemExit('guard-v3 already applied; edit the current JSON dossiers directly.')
groups=['mineral','botanical','creature','material','device','armament','phenomenon','entity','complex']
data={g:json.loads((root/f'{g}.json').read_text()) if (root/f'{g}.json').exists() else [] for g in groups}
snapshot=json.loads((root/'editorial/guard-v3/source-evidence.json').read_text())
evidence=snapshot['excerpts']
tabs=snapshot['chapter_tabs']
by={m['id']:m for a in data.values() for m in a}

def pair(vi,en):return {'vi':vi,'en':en}
def prop(nv,ne,dv,de):return {'name_vi':nv,'name_en':ne,'description_vi':dv,'description_en':de}
def source(*keys):return [{k:v for k,v in evidence[key].items() if k!='paragraph'} for key in keys]
def fields(m,key,vi,en):m[key+'_vi']=vi;m[key+'_en']=en
def quantity(m,kind='unknown',count=None,vi='',en=''):
 m['quantity']={'kind':kind,'note_vi':vi,'note_en':en}
 if count is not None:m['quantity']['count']=count
def put(id,category,rank,nv,ne,fv,fe,lv,le,uv,ue,limv,lime,skills,traits,keys=(),owner=('', ''),number=None,spanish=None,editorial=False):
 m=by.get(id,{'id':id,'category':category})
 m.update(rarity=rank,origin='canon' if keys else 'collection',skills=skills,traits=traits,sources=source(*keys),content_revision='guard-v3')
 for k,vi,en in [('name',nv,ne),('form',fv,fe),('lore',lv,le),('use',uv,ue),('limits',limv,lime),('owner',*owner),('behavior','','')]:fields(m,k,vi,en)
 fields(m,'rarity_note',('Bậc trưng bày do biên tập đề xuất; bản thảo chưa xác nhận bậc riêng của sản phẩm. ' if editorial else 'Bậc hồ sơ được giữ theo căn cứ lưu trữ hiện hành. ')+('Tên gọi mô tả được bổ sung cho triển lãm; cơ chế dưới đây đối chiếu từ truyện.' if keys else 'Hồ sơ sáng tác mở rộng cho bộ sưu tập, chưa xuất hiện trong truyện.'),('Editorial display rank; the manuscript has not confirmed this creation’s independent rank. ' if editorial else 'Catalogue rank retained from the current archival evidence. ')+('Descriptive naming is supplied for the exhibition; the workings below are checked against the story.' if keys else 'An original collection expansion, not yet attested in the story.'))
 quantity(m,'singleton',1,'Hồ sơ theo dõi một trang bị gắn với người mang số hiệu này; số lượng không xác định bậc sức mạnh.','This dossier follows one equipment manifestation bound to this bearer; quantity does not determine power rank.')
 if number:m['royal_guard']={'number':number,'label':spanish,'relation':'deployment','parent_id':'device-003'}
 if id not in by:data[category].append(m);by[id]=m
 return m

# One series dossier, with legacy Cuatro deep links resolved by the UI.
parent=by['device-003']
fields(parent,'name','Dây chuyền Cận vệ Hoàng gia','Royal Guard Pendants')
fields(parent,'form','Hệ một trăm mặt sư tử đánh số từ 1 đến 100','A series of one hundred numbered lion-face pendants')
fields(parent,'owner','Cận vệ Hoàng gia Castilian','The Castilian Royal Guard')
fields(parent,'lore','Một trăm gương mặt sư tử nằm dưới những cổ áo quân phục. Mỗi mặt mang một con số, và mỗi con số gắn với một người đã được ngai Castilian giao phần sinh tử của mình. Uno, Dos, Ocho hay Ochenta y Nueve đều thuộc cùng một hệ ấn hiệu. Số hiệu ghi vị trí cùng trách nhiệm trong hàng ngũ Cận vệ; lòng tin của vương quyền mang trọng lượng riêng bên cạnh tài nghệ chiến đấu.\n\nBản thân dây chuyền thuộc bậc Kỳ tích. Khi được triển khai, nó có thể tạo nên trang bị với bậc riêng từ Kỳ tích đến Độc bản. Qua từng người mang, cùng một gương mặt sư tử mở ra những điều rất khác: sợi chỉ giữ một cơ thể sống, bảy khối dựng cầu giữa chiến trường, hay bầu trời mười hai chòm sao khép sau vai một cận vệ. Bộ sưu tập lưu cả hệ bằng một hiện vật đại diện; những gì sinh ra từ nó có hồ sơ riêng phía dưới.','One hundred lion faces rest beneath military collars. Each bears a number, and each number belongs to someone entrusted with a share of the Castilian throne’s survival. Uno, Dos, Ocho and Ochenta y Nueve belong to the same system of insignia. A number records a place and its responsibilities within the Guard; royal trust carries its own weight alongside martial accomplishment.\n\nThe pendants themselves are Wondrous. Their deployed creations carry independent ranks ranging from Wondrous to Unique. Across different bearers, the same lion face opens onto very different things: a thread holding a body together, seven blocks bridging a battlefield, or twelve constellations closing behind a guardian’s shoulders. One representative exhibit records the whole series; its creations receive separate dossiers below.')
fields(parent,'use','Triển khai trang bị gắn với từng người mang. Chọn một sản phẩm trong bộ sưu tập để đọc cơ chế, điều kiện và trạng thái riêng của nó.','Deploys equipment associated with each bearer. Open a creation in the collection for its particular workings, conditions and states.')
parent['royal_guard']={'relation':'representative','parent_id':None}
parent['sources']=source('pendants','orbis','zodiac','uno')
quantity(parent,'finite',100,'Toàn hệ có 100 số hiệu. Đây là hồ sơ đại diện, không phải một trăm món trùng nhau trên kệ.','The series contains 100 numbered places. This is a representative dossier, not one hundred duplicate shelf entries.')
parent['content_revision']='guard-v3'
data['device']=[m for m in data['device'] if m['id']!='device-065']
by.pop('device-065',None)

put('complex-uno-speculum','complex',6,'Uno. Thế Giới Xích Gương Speculum','Uno. World of Mirrored Chains Speculum','Miền gương và xích của Uno','Uno’s field of mirrors and chains',
'Tiếng kính đầu tiên vang lên từ rất xa trong đá Hoàng cung. Rồi sàn, cột và cả khoảng không bắt đầu có những mặt gương của riêng mình. Sợi xích nằm ngoài chúng đã biến mất, còn trong mỗi mặt phản chiếu, nó chờ ở một vị trí khác. Khi Testarossa đưa tay, những khả thể ấy cùng áp sát một hiện tại đang bị giằng xé.\n\nUno triển khai một miền nơi phản chiếu có thể nhận lấy trọng lượng của sự thật. Trong cuộc vây hãm, miền ấy cản trở sự hội tụ của đôi búp bê, mở đường cho Isabella và buộc mỗi đối thủ phải tính đến nhiều vị trí có thể thành thực cùng lúc. Speculum là tên lưu trữ được đặt cho tổ hợp này; những vết thương cùng máu của người sử dụng vẫn đi theo nó qua mặt kính.',
'The first glass-note rang from far inside the palace stone. Then floor, pillars and unsupported air acquired mirrors of their own. The chain outside them vanished, while each reflection held it in a different position. When Testarossa raised her hand, those possibilities closed upon a present already being torn apart.\n\nUno deploys a field in which a reflection can acquire the weight of truth. During the siege it disrupted the dolls’ convergence, opened a passage for Isabella and forced enemies to account for several positions capable of becoming real together. Speculum is the archival name supplied for this complex; its bearer’s wounds and blood still follow it through the glass.',
'Khống chế chiến trường bằng nhiều vị trí khả thể, xích trong gương và lối qua mặt phản chiếu.','Controls a battlefield through possible positions, mirrored chains and passages through reflections.',
'Việc duy trì miền gương gắn với tình trạng của người sử dụng. Máu, thương tích và sự kiệt sức được ghi nhận ngay trong trận; chưa có căn cứ cho khả năng nhân bản vô hạn hay hồi phục miễn phí.','Maintaining the field is tied to the bearer’s condition. Blood loss, injury and exhaustion are recorded during the battle; limitless duplication or costless recovery is not established.',
[prop('Đa vị trí khả thể','Multiple Possible Positions','Các mặt gương giữ những vị trí khác nhau có thể cùng trở thành mối đe dọa, gây nhiễu cơ chế chọn một đích duy nhất.','Mirrors retain different positions capable of becoming threats, disrupting mechanisms that select a single target.'),prop('Xích trong phản chiếu','Chains within Reflections','Dẫn xích qua các mặt gương để áp sát từ nhiều hướng, trong khi phần xích tương ứng ngoài gương có thể biến mất.','Routes chains through reflections to approach from several directions while their corresponding lengths outside the mirrors can disappear.'),prop('Cửa gương','Mirror Passage','Một mặt phản chiếu có thể mở thành đường đi thật như cảnh Isabella xuất hiện qua phía bên kia.','A reflection can open into a real passage, as when Isabella emerges on its other side.')],
[prop('Khả thể mang thực tính','Possibilities with Substance','Gương tham gia trực tiếp vào tương tác của chiến trường; tấn công chúng như ảnh giả thông thường có thể để lộ sai lầm chí tử.','Mirrors participate directly in the battlefield; treating them as ordinary false images can expose a fatal mistake.')],('uno','unoMirror'),('Testarossa','Testarossa'),1,'Uno',True)

put('complex-dos-sutura','complex',5,'Dos. Huyết Chỉ Sinh Mệnh Sutura','Dos. Lifeblood Sutures Sutura','Cơ thể sống và mạng chỉ huyết kim','A living body joined by blood-metal threads',
'Dos chảy vào Scarlet, và các khớp của cô rời chốt. Vai, hông, xương sườn tách ra giữa những sợi đỏ vẫn giữ quyền thuộc về cùng một cơ thể. Sutura xuất hiện ngay trong ranh giới ấy: máu nhận độ bền của kim loại, còn những phần thân thể xa nhau tiếp tục nghe cùng một ý chí.\n\nTrên chiến trường, mạng chỉ ấy đổi góc đánh và đón lấy người sắp rơi. Trên bàn mổ, nó tìm những đầu mạch đã tuột sâu vào thịt, giữ đường sống cho người mà đôi tay y sĩ khó chạm tới. Scarlet phải hiểu thứ mình đang nối. Một sợi chỉ có thể khép mô; phần đời trở lại trong mô ấy còn cần nhiệt, máu, dưỡng chất và thời gian.',
'Dos flows into Scarlet, and her joints release. Shoulder, hip and ribs separate along red threads that preserve their belonging to one body. Sutura emerges at that boundary: blood takes on the strength of metal, while distant portions of flesh continue to answer one will.\n\nOn a battlefield the network changes her angle of attack and catches the falling. On an operating table it finds vessels withdrawn deep into flesh and holds a path for life where a surgeon’s hands struggle to reach. Scarlet must understand what she joins. A thread can close tissue; the life returning through it still needs warmth, blood, nourishment and time.',
'Chiến đấu đa hướng, cứu hộ, nối mô và hỗ trợ can thiệp ngoại khoa.','Multi-angle combat, rescue, tissue reconnection and surgical support.',
'Dùng dự trữ của Scarlet. Tổn thương thần kinh cần xử lý riêng; nối mô không bảo đảm phục hồi chức năng. Bệnh nhân vẫn cần nhiệt, đường huyết và oxy. Khi Dos cạn, khả năng phân tách cơ thể bị hạn chế.','Draws on Scarlet’s reserves. Nerve damage requires separate treatment; joining tissue does not guarantee restored function. Patients still need warmth, glucose and oxygen. An exhausted Dos restricts bodily separation.',
[prop('Phân thể liên kết','Linked Disarticulation','Tách các phần cơ thể trong mạng chỉ để thay đổi vị trí và góc tác động mà vẫn giữ liên kết điều khiển.','Separates body portions within a thread-network to change position and angle while retaining control.'),prop('Khâu mạch sinh mệnh','Vital Suturing','Nối mô, cơ và mạch máu theo cấu trúc Scarlet nhận biết, hỗ trợ giữ bệnh nhân qua giai đoạn nguy kịch.','Reconnects recognised tissue, muscle and vessels to help carry a patient through a critical interval.'),prop('Kén huyết chỉ','Blood-Thread Cocoon','Kết chỉ thành lớp đỡ, quấn giữ và dẫn kéo người hoặc vật qua khoảng nguy hiểm.','Weaves supportive cocoons and tethers to hold and draw people or objects across danger.'),prop('Mạch khâu độc lập','Independent Suture Circuits','Chia mạng thành các vòng khép riêng để giảm phản hồi cưỡng ép trong tình huống mạng chỉ bị đối phương can thiệp.','Divides the network into separate closed circuits to reduce forced feedback when an enemy interferes with it.')],
[prop('Thân thể là một phần hệ','Body as Part of the System','Sutura triển khai trực tiếp vào Scarlet; cô vừa điều khiển vừa là thành phần sống của tổ hợp.','Sutura deploys directly into Scarlet; she is both its operator and its living component.')],('dos','dosHealing','dosLimits'),('Scarlet','Scarlet'),2,'Dos',True)

put('device-cuatro-zodiacum','device',6,'Cuatro. Thiên Đồ Thập Nhị Zodiacum','Cuatro. Twelvefold Firmament Zodiacum','Vòng thiên đồ mười hai cung, trạng thái mở khóa Starfall','A twelve-sign celestial array with an unlocked Starfall state',
'Khi Cuatro thức dậy, một vòng tinh quang dựng sau lưng Evelyne. Mười hai chòm sao nhận vị trí theo thứ tự, và mỗi lần chuyển cung mang theo một cách can dự khác vào trận đánh. Trên cao là hình trời; ở dưới là những quyết định phải trả bằng chính phần sáng còn lại trong thiên đồ.\n\nTrong trạng thái thường, chuỗi đã khởi động tiếp tục theo trật tự cố định. Chiếc khóa đặc biệt ở Hoàng cung mở ra Starfall, cho phép Evelyne chọn và gọi lại các cung. Nàng dùng Scorpio thu dấu hành vi, Sagittarius cắt những liên kết đã được xác định, Capricorn dựng những lớp chắn chịu lực. Mỗi lần gọi lại, một phần trời tối xuống, và vết nứt trên mặt dây IV tiến sâu thêm.',
'When Cuatro wakes, a ring of starlight rises behind Evelyne. Twelve constellations take their ordered places, each transition bringing a different intervention into battle. Above is the shape of heaven; below are decisions paid for with the light still remaining in its chart.\n\nIn its ordinary state, an initiated sequence follows a fixed order. A special palace key opens Starfall, allowing Evelyne to select and repeat signs. Scorpio gathers behavioural traces, Sagittarius cuts identified connections and Capricorn raises layered barriers. Each repeated summons darkens another portion of the sky and drives the crack across the numeral IV deeper.',
'Phân tích dấu hành vi, đánh trúng liên kết và phòng hộ theo cơ chế từng cung.','Reads behavioural traces, strikes connections and provides protection through the distinct workings of its signs.',
'Chuỗi thường có thứ tự cố định và có hệ quả khi cắt sớm. Starfall phụ thuộc điều kiện mở khóa, dùng chung một tổng năng lượng; gọi lại cung làm cạn phần sáng còn lại, gây nóng, đau và nứt mặt dây.','The ordinary sequence has a fixed order and consequences for early interruption. Starfall requires its unlocking condition and shares one total energy reserve; repeated signs drain remaining light and produce heat, pain and cracks in the pendant.',
[prop('Mười hai sao','Twelve Stars','Triển khai vòng cung sao theo chuỗi đã khóa khi bắt đầu. Các cung về sau phụ thuộc tiến trình của chuỗi.','Deploys a constellation ring in a sequence locked upon initiation; later signs depend on its progression.'),prop('Scorpio','Scorpio','Ghi dấu hành vi để hỗ trợ dự đoán và chọn điểm tác động trong trận.','Records behavioural traces to assist prediction and the selection of targets.'),prop('Sagittarius','Sagittarius','Dùng dữ liệu ngắm để đánh và cắt các liên kết đã xác định.','Uses targeting information to strike and sever identified connections.'),prop('Capricorn','Capricorn','Dựng các lớp chắn chịu lực; chúng có thể vỡ dưới tải đủ lớn.','Raises load-bearing barrier layers that can break under sufficient force.'),prop('Starfall','Starfall','Sau mở khóa, lựa chọn và lặp cung trong cùng quỹ năng lượng của thiên đồ.','Once unlocked, selects and repeats signs within the celestial array’s shared reserve.')],
[prop('Cùng một bầu trời','One Shared Sky','Mọi lần lặp cung cùng rút từ tổng năng lượng hữu hạn. Dữ liệu quan sát vẫn cần được thu và hiệu chỉnh.','Every repeated sign draws from one finite reserve. Observational information still has to be gathered and corrected.')],('zodiac','starfall','starfallLimits'),('Evelyne Vesper','Evelyne Vesper'),4,'Cuatro',True)

# Preserve existing art for existing gear; expand their profiles from verified scenes.
guardExisting={
 'armament-marco-octava-forja':(8,'Ocho','Công Xưởng Thất Khối','Seven-Block Foundry','Octava Forja'),
 'armament-romeo-oathbreaker':(12,'Doce','Lôi Phủ Phá Thệ','Oathbreaking Thunderaxe','Oathbreaker'),
 'armament-oathbearer':(12,'Doce','Thiết Thủ Thừa Lôi','Thunder-Bearing Hand','Oathbearer'),
 'armament-northwall':(22,'Veintidós','Song Thuẫn Bắc Thành','Northern Rampart Shields','Northwall'),
 'armament-winterthorn':(32,'Treinta y Dos','Liễu Kiếm Đông Cức','Winterthorn Rapier','Winterthorn'),
 'armament-skoll-hati':(42,'Cuarenta y Dos','Song Nha Truy Nguyệt','Moon-Chasing Fangs','Sköll và Hati'),
 'armament-gleipnir':(52,'Cincuenta y Dos','Tơ Khóa Liệp Ảnh','Shadow-Hunting Tethers','Gleipnir'),
}
for id,(num,spanish,title,enTitle,proper) in guardExisting.items():
 m=by[id];m['royal_guard']={'number':num,'label':spanish,'relation':'deployment','parent_id':'device-003'}
 fields(m,'name',f'{spanish}. {title} {proper}',f'{spanish}. {enTitle} '+proper.replace(' và ',' and '))
 quantity(m,'singleton',1,'Một hệ trang bị gắn với người mang số hiệu; các bộ phận được tính chung trong hệ.','One equipment system bound to its numbered bearer; constituent parts belong to that system.')
 fields(m,'rarity_note','Bậc trưng bày biên tập của sản phẩm; bậc Kỳ tích của dây chuyền và sabre nền được ghi riêng. Tên mô tả được bổ sung cho triển lãm.','Editorial display rank for the creation; the Wondrous ranks of the pendant and base sabre are recorded separately. Descriptive titles are supplied for the exhibition.')
 m['content_revision']='guard-v3'

m=by['armament-marco-octava-forja'];m['sources']=source('octava')
fields(m,'lore','Trong tay Marco, một lưỡi thép mở thành công xưởng. Búa Octava Forja giữ quyền chỉ huy bảy khối đen viền vàng; từng khối xoay cạnh, đổi mặt và chờ một cấu trúc mới được gọi tên. Ở Fes, chúng trở thành cầu, công sự, bộ phận máy. Giữa Hoàng cung, hai khối nhận làm cột, ba khối chịu vai xà, hai khối giăng lưới đỡ người phía dưới.\n\nCái tên công xưởng còn mang theo những lần thất bại. Thử nghiệm đạn khối lập phương từng làm hỏng năm khẩu pháo. Khi Romeo truyền điện vào chúng, Marco có thêm một con đường tích và phóng lực; người thợ đứng giữa trận phải quyết định cấu trúc nào chịu nổi sức mạnh mình vừa vay.','In Marco’s hands, a blade opens into a foundry. The Octava Forja hammer commands seven black cubes edged in gold; each turns, changes its faces and awaits the naming of a new structure. At Fes they became bridges, fortifications and machine parts. In the palace, two became columns, three bore the role of beams and two spread a net beneath the falling.\n\nA foundry’s name also carries its failures. Cube-projectile trials once damaged five cannon. When Romeo charged them with lightning, Marco gained another means of storing and launching force; the craftsman amid the battle must judge which structure can bear the strength he has borrowed.')
m['skills']=[prop('Tái cấu hình thất khối','Seven-Block Reconfiguration','Sắp bảy khối thành cấu trúc công binh, giá đỡ, lưới và các bộ phận máy theo thao tác điều khiển của Marco.','Arranges seven cubes into engineering structures, supports, nets and machine components under Marco’s control.'),prop('Búa chỉ huy','Command Hammer','Dùng búa điều khiển hệ khối và truyền lực vào cấu trúc đã dựng.','Uses the hammer to direct the cube system and transfer force into assembled structures.'),prop('Tích và phóng năng lượng','Energy Storage and Release','Tiếp nhận năng lượng ngoại lai trong thử nghiệm, phối hợp điện của Oathbearer để tạo đạn khối.','Receives external energy in experimental structures, cooperating with Oathbearer’s lightning to form cube projectiles.')]
m['traits']=[prop('Bảy cấu kiện','Seven Components','Số khối được ghi nhận là bảy. Mỗi cấu trúc chiếm một phần hữu hạn của cùng hệ.','Seven cubes are recorded. Each construction occupies a finite share of the same system.')]
m=by['armament-romeo-oathbreaker'];m['sources']=source('oathbreaker')
fields(m,'lore','Doce truyền điện xuống sabre của Romeo. Thép dồn về chuôi rồi nở thành hai lưỡi rìu, những đường sét bò quanh đầu vũ khí trong không khí lạnh. Oathbreaker biến nhịp đấu kiếm thành những cú bổ có thể ép đối thủ đổi cả thế đứng. Người mang nó vẫn phải mang theo trọng lượng của mỗi lần vung.\n\nKhi Oathbearer xuất hiện trên tay trái, chiếc rìu giữ căn tính của riêng mình. Cả hai có thể cùng hiện diện, trao cho Romeo một bên để phá và một bên để dẫn lôi. Những cảnh chiến đấu kéo dài ghi lại lúc điện cạn, hơi thở nặng và trận đánh trở về với sức người còn lại dưới lớp quân phục.','Doce carries lightning into Romeo’s sabre. Steel gathers at the hilt and opens into two axe-blades, electrical lines crawling over the head in the cold air. Oathbreaker turns a fencing rhythm into hewing blows capable of forcing an enemy to change his entire stance. Its bearer still carries the weight of every swing.\n\nWhen Oathbearer appears upon his left hand, the axe keeps its own identity. Both can be present together, giving Romeo one side for breaking and one for conducting thunder. Prolonged fights record the electricity fading, breath growing heavy and battle returning to the human strength left beneath the uniform.')
m=by['armament-oathbearer']
fields(m,'limits','Dòng điện lớn gây quá tải; trong trận tại Hoàng cung, găng đã nứt. Tia sét đầu tiên của Romeo từng giáng quá gần Marco. Điều khiển và vị trí đồng đội là điều kiện sống còn.','Heavy current can overload it; the gauntlet cracks during the palace battle. Romeo’s first called bolt strikes dangerously close to Marco. Control and allied positions are matters of survival.')
m['skills']=[prop('Gọi lôi','Call Lightning','Dẫn sét qua tay mang găng rồi phóng vào mục tiêu đã chọn.','Conducts lightning through the gauntleted hand and releases it at a chosen target.'),prop('Tiếp năng công xưởng','Charge the Foundry','Truyền điện cho các khối Octava Forja trong thao tác phối hợp cùng Marco.','Transfers electricity into Octava Forja’s cubes in coordinated work with Marco.')]
m['traits']=[prop('Hình thái bổ sung của Doce','Additional Doce Manifestation','Cùng tồn tại với rìu Oathbreaker; hai sản phẩm được lưu bằng hai hồ sơ liên kết cùng một số hiệu.','Can coexist with the Oathbreaker axe; the two creations receive separate dossiers linked to one numbered pendant.')]

put('armament-cuarenta-cuatro-sarab','armament',4,'Cuarenta y Cuatro. Nguyệt Liềm Hư Bộ Sarāb','Cuarenta y Cuatro. Phantom-Step Crescent Sarāb','Shotel cong gắn với trạng thái lệch pha của Nahla','A curved shotel linked to Nahla’s phase state',
'Nahla al-Fassi lớn lên tại Fes trong một nhánh Reliquario của Maroc. Sau khi năng lực ổn định, cô được chuyển sang Cận vệ và nhận số Cuarenta y Cuatro. Khi sabre mở thành Sarāb, đường cong của shotel trao cho mỗi bước áp sát một khoảng thời gian đối phương khó nắm bắt.\n\nNăm giây đủ để đi qua một đường giáo, lách sát nòng súng, đưa lưỡi thép tới nơi người giữ khiên tin mình được che kín. Năm giây tiếp theo thuộc về thân thể có thể bị thương của cô. Nahla chiến đấu trong nhịp thay phiên ấy, mang theo ký ức Fes và sự tỉnh táo của người biết tiếng nổ vẫn tìm được mình giữa một bước hư.','Nahla al-Fassi grew up in a Moroccan Reliquario branch in Fes. Once her ability stabilised, she transferred to the Royal Guard and received Cuarenta y Cuatro. When her sabre opens into Sarāb, the shotel’s curve lends each advance an interval an opponent struggles to grasp.\n\nFive seconds can carry her through a spear-line, past a gun-barrel and into the space a shield-bearer believes protected. The following five belong to her vulnerable body. Nahla fights within that alternating rhythm, carrying Fes in memory and the composure of someone who knows an explosion can still find her during a phantom step.',
'Áp sát và đánh vòng sau phòng thủ bằng shotel cùng cửa sổ lệch pha ngắn.','Closes distance and reaches around defences with a shotel and a short phase window.',
'Lệch pha tối đa năm giây, chờ ít nhất năm giây giữa hai lần. Mảnh văng, lửa, sóng xung kích và vụ nổ vẫn gây thương tích.','The phase lasts five seconds, with at least five seconds before reuse. Fragments, fire, shock waves and explosions remain harmful.',
[prop('Hư bộ ngũ tức','Five-Second Phase','Trong năm giây, kiếm, giáo và đạn chì bay thẳng thường khó chạm Nahla.','For five seconds, swords, spears and straight-flying lead shot generally struggle to touch Nahla.'),prop('Liềm vòng thủ thế','Guard-Reaching Crescent','Hình cong của shotel hỗ trợ đánh vòng qua mép khiên khi cô áp sát đúng thời điểm.','The shotel’s curve supports reaching around a shield edge when she closes at the right moment.')],
[prop('Còn trong không gian','Still within Space','Lệch pha vẫn để Nahla chịu các hiểm họa lan rộng trong cùng chiến trường.','Phasing still leaves Nahla exposed to spreading hazards in the same battlefield.')],('alFassi','sarab'),('Nahla al-Fassi','Nahla al-Fassi'),44,'Cuarenta y Cuatro',True)

put('armament-cincuenta-cinco-qamar','armament',4,'Cincuenta y Cinco. Luân Nguyệt Du Hành Qamar','Cincuenta y Cinco. Wandering Moonwheel Qamar','Chakram lớn gắn với lệch pha của Samira','A great chakram linked to Samira’s phase state',
'Samira al-Fassi mang số Cincuenta y Cinco, cùng chị rời nhánh Reliquario ở Fes để bước vào hàng ngũ Cận vệ. Vũ khí của cô nở thành một vòng nguyệt lớn: Qamar. Khi vòng rời tay và tiếp tục bay, cơ thể cô bước vào khoảng lệch mà những đòn trực tiếp khó bắt kịp.\n\nMỗi lần ném trao sự an toàn của người mang cho quỹ đạo của một vật khác. Samira phải đọc khoảng trống, bề mặt và bàn tay đối phương. Một vòng trăng bị ghim vào tường có thể lập tức trả cô về giữa đường đạn; khoảnh khắc thu hồi cũng là khoảnh khắc thân thể nhận lại mọi hiểm nguy.','Samira al-Fassi bears Cincuenta y Cinco, having left the Reliquario branch at Fes with her sister to enter the Guard. Her weapon opens into a great moon-ring: Qamar. While it has left her hand and remains in flight, her body enters a phase direct blows struggle to catch.\n\nEach throw entrusts the bearer’s safety to another object’s path. Samira must read open space, surfaces and enemy hands. A moon-ring pinned into a wall can return her instantly to the gun-line; retrieval is also the instant her body takes back its dangers.',
'Chiến đấu bằng vòng ném và di chuyển trong khoảng lệch pha gắn với chuyến bay của Qamar.','Fights with a throwing ring and moves through a phase window tied to Qamar’s flight.',
'Qamar phải rời tay và còn chuyển động. Thu hồi, bị chặn hoặc bị ghim lập tức chấm dứt lệch pha. Vụ nổ và nguy hiểm diện rộng vẫn có thể gây thương tích.','Qamar must be out of her hand and still moving. Retrieval, interception or pinning immediately ends the phase. Explosions and broad hazards can still injure her.',
[prop('Vòng nguyệt xuất thủ','Moonwheel in Flight','Ném Qamar qua đường cong chiến đấu và duy trì khoảng lệch pha khi vòng vẫn bay.','Casts Qamar along a fighting arc and sustains the phase while the ring remains airborne.')],
[prop('An toàn theo quỹ đạo','Safety Bound to a Trajectory','Trạng thái cơ thể liên kết trực tiếp với chuyển động của vũ khí. Đối phương có thể tấn công quỹ đạo để buộc Samira trở lại.','Her bodily state is directly linked to the weapon’s motion. An enemy can attack that trajectory to force her return.')],('alFassi','qamar'),('Samira al-Fassi','Samira al-Fassi'),55,'Cincuenta y Cinco',True)

put('device-ochenta-nueve-orbis','device',4,'Ochenta y Nueve. Hải Quyền Tam Khí Orbis','Ochenta y Nueve. Three Instruments of Sea Dominion Orbis','Kính viễn vọng, la bàn và hải đồ triển khai cùng nhau','A telescope, compass and sea-chart deployed together',
'Dưới cổ áo hải quân của Morales là số 89. Khi ông đặt mặt sư tử giữa hai ngón tay, Orbis hiện ra trên thùng gỗ: kính đồng đen, la bàn trống phương hướng, hải đồ trắng chưa có một tên bờ biển. Gió biển bắt đầu viết lên mặt giấy. Những con tàu tìm thấy vị trí của mình, và trận đánh nhận một hình hài có thể đọc được.\n\nMorales giữ kính đủ lâu trên một chiến hạm, tìm điểm nơi thuốc súng, dầm chịu lực và sức căng thân tàu cùng có thể sụp đổ. Dấu đỏ ấy chỉ ông nhìn thấy. La bàn dành cho con tàu ông đang đứng một hướng tránh chìm; phần sống còn của các tàu khác vẫn nằm trong quyết định của người chỉ huy. Orbis đưa cho một đô đốc ba cách nắm lấy biển, cùng trách nhiệm đối với mọi người nằm ngoài lời bảo đảm của nó.','The number 89 rests beneath Morales’s naval collar. When he holds the lion face between two fingers, Orbis appears upon a wooden cask: a black-bronze telescope, a compass without directions and a blank chart bearing no coast’s name. Sea-wind begins to write upon the paper. Ships find their positions, and battle acquires a readable shape.\n\nMorales holds the telescope upon a warship long enough to find the point where powder, supporting timbers and the hull’s tension can fail together. Only he sees its red mark. The compass offers the ship beneath his feet a heading that avoids sinking; the survival of the other vessels remains with their commander’s decisions. Orbis gives an admiral three ways to grasp the sea, together with responsibility for everyone beyond its guarantee.',
'Chỉ thị điểm chí tử chiến hạm, chọn hướng tránh chìm cho tàu của Morales và lập hải đồ sống bằng gió biển.','Marks a warship’s fatal point, selects a non-sinking heading for Morales’s own ship and draws a living chart through sea-wind.',
'Cần giữ kính trên mục tiêu đủ lâu và bắn trúng đúng điểm đánh dấu. La bàn bảo đảm tránh chìm cho tàu của Morales trong phạm vi được mô tả, không bao gồm thắng trận, thương vong hay cả hạm đội. Hải đồ cần gió biển.','The telescope must hold its target long enough, followed by a shot striking the marked point. The compass’s recorded protection concerns Morales’s ship avoiding sinking; victory, casualties and the whole fleet lie beyond that promise. The chart requires sea-wind.',
[prop('Điểm chết của chiến hạm','A Warship’s Fatal Point','Chọn một điểm chí tử đỏ chỉ Morales nhìn thấy. Đạn pháo trúng đúng điểm có thể khởi phát chuỗi nổ phá hủy con tàu.','Selects one red fatal point visible only to Morales. A cannonball striking it can trigger a chain explosion destroying the vessel.'),prop('Hướng tàu còn nổi','A Heading That Stays Afloat','La bàn chỉ hướng để chính con tàu Morales đang đi tránh bị chìm.','The compass indicates a heading by which Morales’s own ship avoids sinking.'),prop('Hải đồ đón gió','Wind-Written Sea-Chart','Mở hải đồ trước gió biển để hiện bờ, tàu, đội hình và chuyển động quanh trận.','Exposes the chart to sea-wind to reveal coasts, vessels, formations and movements around the engagement.')],
[prop('Một bộ ba hải cụ','Three Instruments, One System','Ba thành phần có chức năng riêng và cùng thuộc một lần triển khai Orbis.','Three components have distinct functions and belong to one Orbis deployment.')],('orbis','orbisPower','orbisRank'),('Đô đốc Morales','Admiral Morales'),89,'Ochenta y Nueve',True)

put('armament-siete-fidelis','armament',4,'Siete. Trọng Đao Lạc Thệ Fidelis','Siete. Oath-Strayed Greatblade Fidelis','Hình thái trọng đao bị can thiệp của Siete','Siete’s externally altered greatblade state',
'Siete đã đáp lời Victoria trong biến cố đôi búp bê ở Hoàng cung, ngay cả khi mặt dây còn nằm trong hộp kín. Một bản thép khổng lồ xuất hiện, khác với hình thái thường được Evelyne nhận biết. Nó dài thêm sau những lần sát thương, nhẹ đi trong cổ tay Victoria và nặng tới mức làm nứt đá dưới mũi.\n\nHồ sơ này giữ lại một trạng thái bị can thiệp. Những cự ly co lại, nhận thức lệch hướng và lời thề bị lợi dụng thuộc về biến cố Cô Dâu, Chú Rể. Fidelis là tên biên mục bổ sung cho hình thái ấy; năng lực chuẩn của Siete cần được đọc riêng khi bản thảo xác lập đầy đủ.','Siete answered Victoria during the palace dolls’ crisis even while its pendant remained in a closed box. A vast steel blade appeared, differing from the ordinary form Evelyne recognised. It lengthened after inflicting harm, grew lighter at Victoria’s wrist and heavy enough to crack stone beneath its point.\n\nThis dossier preserves an interfered-with state. Contracted distances, distorted perception and an exploited oath belong to the Bride and Bridegroom incident. Fidelis is an editorial catalogue name for that state; Siete’s ordinary powers require a separate account when fully established in the manuscript.',
'Ghi nhận hình thái trọng đao và biến đổi tải trọng trong biến cố bị chi phối.','Records the greatblade form and altered load during an episode of external control.',
'Chỉ áp dụng cho trạng thái quan sát trong biến cố búp bê. Những biến đổi khoảng cách thuộc tác động của búp bê và không được gán thành kỹ năng thường của Siete.','Applies only to the state observed during the dolls’ crisis. Distance changes belong to the dolls’ influence and are not assigned as an ordinary Siete ability.',
[prop('Trọng đao biến tải','Changing-Load Greatblade','Trong trạng thái bị can thiệp, bản thép tăng kích thước và thay đổi cảm nhận trọng lượng ở tay người mang.','In the interfered-with state, the blade grows and alters the weight perceived by its bearer.')],
[prop('Hình thái dị thường','Aberrant State','Bản ghi phân biệt trang bị của Victoria với tác động chi phối từ đôi búp bê.','The record distinguishes Victoria’s equipment from the dolls’ controlling influence.')],('sieteMore',),('Victoria','Victoria'),7,'Siete',True)

# Academy swords are independent objects, even when used as deployment substrates.
for slug,owner in [('edward','Edward'),('marco','Marco'),('romeo','Romeo'),('victoria','Victoria')]:
 id=f'armament-{slug}-academy-sabre'
 if id not in by:
  model=json.loads(json.dumps(by['armament-edward-academy-sabre']));model['id']=id;data['armament'].append(model);by[id]=model
 m=by[id];fields(m,'name',f'Sabre Học viện của {owner}',f'{owner}’s Academy Sabre');fields(m,'owner',owner,owner)
 fields(m,'lore',f'Học viện Hoàng gia chỉ trao bốn thanh sabre cho bốn học viên đứng đầu khóa: Edward, Marco, Romeo và Victoria. Các thợ rèn dùng những mảnh Vestigium được xác định là tàn tích Excalibur làm lõi. {owner} giữ một thanh trong bộ ấy.\n\nKhi bốn mũi kiếm chạm nhau, ánh vàng cộng hưởng nối chúng lại trong cùng một khoảnh khắc. Mỗi thanh mang một hành trình riêng sau ngày tốt nghiệp, nhưng dấu nhận biết của bộ bốn còn nằm trong lõi thép. Hồ sơ này lưu thanh sabre gốc; các hình thái được dây chuyền Cận vệ triển khai có mục riêng.',f'The Royal Academy awarded only four sabres to its four leading graduates: Edward, Marco, Romeo and Victoria. Their smiths used Vestigium fragments identified as remnants of Excalibur for the cores. {owner} keeps one blade from that set.\n\nWhen their four points touch, a golden resonance joins them for a moment. Each sword follows its own road after graduation, yet the sign of the four remains within the steel. This dossier records the original sabre; forms deployed through Royal Guard pendants have separate entries.')
 m['sources']=source('academy','academyRank');m['rarity']=4;m['royal_guard']={'relation':'academy'};m['content_revision']='guard-v3'
 m['skills']=[prop('Cộng hưởng bộ bốn','Four-Blade Resonance','Chạm bốn mũi sabre để hiện cộng hưởng vàng giữa những lõi có cùng nguồn.','Touch the four sabre-points to reveal a golden resonance between cores of shared origin.')]
 m['traits']=[prop('Lõi tàn tích Excalibur','Excalibur-Remnant Core','Những mảnh được thợ rèn xác định là tàn tích Excalibur tạo nên lõi của bộ kiếm.','Fragments identified by the smiths as Excalibur remnants form the blades’ cores.')]
 fields(m,'use','Sabre cá nhân bậc Kỳ tích; liên kết cộng hưởng với ba thanh cùng bộ.','A personal Wondrous sabre with a resonance linking the other three in its set.')
 fields(m,'limits','Bản ghi xác nhận nguồn lõi và cộng hưởng. Các năng lực phát sinh khi phối hợp dây chuyền được ghi ở hồ sơ sản phẩm tương ứng.','The record confirms core provenance and resonance. Powers arising through pendant cooperation are recorded under the corresponding creations.')
 fields(m,'rarity_note','Kỳ tích được xác nhận trực tiếp cho cả bốn thanh ở Chương 3. Mỗi thanh là một hiện vật riêng trong bộ bốn.','Chapter 3 explicitly confirms all four blades as Wondrous. Each is an individual object within a set of four.')
 quantity(m,'singleton',1,'Một thanh của bộ bốn sabre Học viện. Đơn chiếc về số lượng, bậc Kỳ tích về sức mạnh.','One blade from the set of four Academy sabres. A singleton by quantity, Wondrous by power rank.')

# Original guard additions intentionally labelled as collection content.
originals=[
('armament-sesenta-uno-ignifer',5,61,'Sesenta y Uno','Lò Tâm Hành Quân Ignifer','Marching Hearth Ignifer','Bộ giáp lò có ống dẫn nhiệt và ba mũi thương rỗng','A furnace harness with heat conduits and three hollow lances',
'Trong một đoàn quân mắc kẹt giữa đồng băng, một cận vệ đã cõng lò sưởi bị vỡ đi suốt đêm. Đến bình minh, than trong lò tắt hết mà bàn tay những người bám sau anh vẫn ấm. Ignifer được biên soạn từ ý niệm ấy: số Sáu Mươi Mốt triển khai một buồng lửa có thể nhận sức nóng đã được trao cho nó rồi dẫn tới những đầu nối xa thân người mang.\n\nMột mũi thương cắm xuống đất làm nền trú quân. Mũi thứ hai luồn vào nồi hơi. Mũi cuối cùng giữ bên y sĩ. Cùng thứ nhiệt đã cứu một trại quân có thể được dồn thành một lần phóng xuyên qua giáp băng; người mang phải chọn phần lửa nào ở lại với người sống.',
'A guard once carried a broken stove through a night in which his column was trapped upon frozen fields. By dawn its coal was dead, yet the hands of those following him remained warm. Ignifer is authored from that idea: Number Sixty-One deploys a fire-chamber that receives heat freely delivered to it and conducts it towards outlets distant from its bearer.\n\nOne lance goes into the ground to prepare a refuge. Another enters a boiler. The last stays beside the surgeon. The same heat that saves a camp can be concentrated into a discharge through ice-armour; its bearer must choose which portion of fire remains with the living.',
'Phân phối nhiệt cho trại, quân y, động cơ và đòn công phá có chuẩn bị.','Distributes heat to camps, medicine, engines and prepared breaching strikes.',
'Kho nhiệt phải được nạp. Dẫn quá nhiều nhiệt vào một nhánh làm các nhánh khác nguội đi; đứt ống có thể phóng nhiệt tại chỗ.','Its heat reserve must be charged. Overfeeding one branch cools the others; a severed conduit can discharge locally.',
[prop('Giữ hỏa chủng','Keep the Ember','Thu nhiệt từ nguồn được nối và giữ trong buồng lò để dùng sau.','Receives heat from an attached source and stores it for later use.'),prop('Ba đường sưởi','Three Warming Lines','Phân phối nhiệt qua ba mũi dẫn, điều chỉnh phần dành cho mỗi nhánh.','Distributes heat through three lances, adjusting the share assigned to each.'),prop('Xuyên hàn','Pierce the Cold','Dồn phần nhiệt dự trữ vào một đầu phóng để phá lớp băng và vật liệu chắn đường.','Concentrates stored heat at one outlet to breach ice and obstructing material.')]),
('device-setenta-seis-ferraria',4,76,'Setenta y Seis','Công Xưởng Dã Chiến Ferraria','Field Foundry Ferraria','Khuôn gấp và bộ ngàm rèn triển khai quanh bàn tay','Folding moulds and forging jaws deployed around the hand',
'Ferraria giữ lại công việc của một người thợ đã thuộc từng lỗ chốt trên khẩu pháo của mình. Khi số Bảy Mươi Sáu triển khai, những ngàm nhỏ xếp quanh bàn tay như một xưởng cơ khí đang mở cửa. Chúng nhận kim loại thật, giữ mẫu hình và ép các phôi thành cấu kiện có thể thay thế nhau.\n\nGiữa chiến dịch, một chốt khóa đúng cỡ có thể quyết định cả khẩu đội còn bắn được hay nằm lại. Ferraria dành phép lạ của mình cho những thứ ít ai ca tụng: bạc lót, đinh tán, khóa nòng và bánh răng. Cái giá của mỗi bản sao nằm trong vật liệu đưa vào và độ chính xác của mẫu mà người thợ chọn tin.',
'Ferraria preserves the work of a smith who knew every pin-hole in his own gun. When Number Seventy-Six deploys, small jaws arrange around the hand like the opening of a mechanical workshop. They receive real metal, retain a pattern and press blanks into interchangeable components.\n\nOn campaign, a correctly sized locking pin can decide whether an entire battery fires again or stays behind. Ferraria devotes its miracle to things seldom praised: bushings, rivets, breech locks and gears. Every copy is paid for in the material supplied and the accuracy of the pattern its smith chooses to trust.',
'Chế tạo cấu kiện thay thế, sửa vũ khí và bảo trì máy trong chiến dịch.','Makes replacement components and repairs weapons and machinery on campaign.',
'Cần vật liệu đủ và mẫu đúng. Lỗi trong mẫu được nhân theo sản phẩm; hệ không tự nhận biết thiết kế nguy hiểm.','Requires sufficient material and a correct pattern. Pattern faults propagate into products; the system does not independently judge unsafe designs.',
[prop('Ghi khuôn','Retain a Pattern','Lưu hình học của cấu kiện tiếp xúc đầy đủ với bộ ngàm.','Retains the geometry of a component fully presented to its jaws.'),prop('Ép phôi','Shape the Blank','Đưa vật liệu vào khuôn để tạo bản sao cấu kiện theo mẫu đã lưu.','Feeds material through the mould to reproduce a retained component pattern.')]),
('complex-noventa-siete-palingenia',7,97,'Noventa y Siete','Di Sản Thành Trì Palingenia','Citadel Inheritance Palingenia','Chuông, chìa khóa và một miền thành quách ký ức','A bell, a key and a remembered citadel-domain',
'Người đúc Palingenia đã chôn tiếng chuông của một thành phố bị xóa tên vào chiếc chìa khóa cuối cùng còn mở được cổng. Khi số Chín Mươi Bảy triển khai, chuông ngân mà không cần quả lắc; đường phố đã mất tìm lại bóng của chúng trên mặt tuyết. Những bậc thềm nhận tiếng chân, giếng nhận gầu, lò bánh nhận hơi nóng của một buổi sáng từng có thật.\n\nMiền thành được dựng bằng những phần đời người mang đã thật sự chứng kiến. Trong nó, một nơi trú có thể được trao thêm một đêm tồn tại, một con đường đã sập có thể lại dẫn người tị nạn qua vực. Mỗi công trình được gọi về lấy đi một ký ức tương ứng trong người giữ chìa. Khi chuông dứt, người sống bước ra; những gì họ mang theo sẽ quyết định thành phố ấy còn được nhớ bởi ai.',
'Palingenia’s maker buried the bells of an erased city within the last key that still opened its gate. When Number Ninety-Seven deploys, the bell rings without a clapper; lost streets recover their shadows upon the snow. Steps receive footsteps, wells receive buckets and ovens receive the warmth of a morning that once existed.\n\nThe citadel-domain is built from lives its bearer truly witnessed. Within it, a refuge can be granted another night of existence and a fallen road can lead refugees across a chasm again. Each recalled structure takes its corresponding memory from the key’s keeper. When the bell falls silent, the living walk out; what they carry will decide who still remembers the city.',
'Gọi lại công trình đã chứng kiến để mở đường và tạo nơi trú tạm trong một miền ký ức có thực tính.','Recalls witnessed structures as temporary routes and refuges within a memory-domain possessing substance.',
'Chỉ nhận những công trình người mang đã trực tiếp trải nghiệm. Ký ức tương ứng bị trao đi khi gọi về; kết cấu tan khi hết hồi chuông. Người trú phải ra ngoài trước lúc miền khép.','Accepts only structures personally experienced by the bearer. Their corresponding memories are surrendered when recalled; structures dissolve with the peal. Occupants must leave before the domain closes.',
[prop('Gọi thành từ ký ức','Recall a Remembered Citadel','Dựng những công trình đã chứng kiến thành nơi có thể đi lại trong miền chuông.','Raises witnessed structures as traversable places within the bell-domain.'),prop('Đường đã từng đi','A Road Once Walked','Gọi lại một tuyến đường trong ký ức để nối qua khoảng địa hình đứt gãy.','Recalls a remembered route to bridge a break in the terrain.'),prop('Đêm trú cuối cùng','One Last Night of Shelter','Giữ một nơi trú hiện hữu trong miền cho tới khi hồi chuông của nó kết thúc.','Sustains a refuge within the domain until its allotted peal ends.')])]
for id,rank,num,sp,nv,ne,fv,fe,lv,le,uv,ue,limv,lime,sk in originals:
 put(id,'complex' if id.startswith('complex') else 'armament' if id.startswith('armament') else 'device',rank,f'{sp}. {nv}',f'{sp}. {ne}',fv,fe,lv,le,uv,ue,limv,lime,sk,[prop('Triển khai theo số hiệu','Number-Bound Deployment','Hồ sơ mở rộng của hệ Cận vệ, dành cho nội dung sáng tác bổ sung.','An expansion of the Guard system authored as additional collection content.')],(),('Chưa xác lập người mang','Bearer not yet established'),num,sp,True)

# Complexes are compound natures, not a basket for all manufactured objects.
complexes=[
('complex-reu-thiet-mam',0,'Mầm Rêu Thiết Tủy','Ironmarrow Moss Bud','Rêu sống bám mạng quặng thức nhiệt','Living moss upon a heat-responsive ore network',
'Một lớp rêu mọc qua vết nứt của thanh quặng đặt cạnh lò đã sống sót sau mùa đông làm chết cả vườn kính. Khi lò nguội, mạng quặng còn giữ nhịp ấm của những ngày trước và trao nó từng chút vào thân rêu. Những mầm mới mọc theo đường sắt trong đá, hình thành một cơ thể phải được ghi bằng cả hai bản chất.\n\nThợ mỏ đặt nó trong hộp ươm, giữ một dấu xanh cạnh cửa hầm. Sự ấm áp nhỏ ấy đủ cho hạt giống qua đêm, và đủ nhắc người gác rằng nơi này vẫn còn một thứ đang lớn.','Moss growing through a furnace-side ore bar survived the winter that killed the rest of a greenhouse. When the furnace cooled, the ore network retained the rhythm of former warmth and released it little by little into the moss. New shoots followed the iron through the stone, forming a body that had to be recorded through both natures.\n\nMiners keep it in nursery boxes, preserving a green mark beside the shaft. Its small warmth can carry seeds through a night and remind a watchman that something here is still growing.',
'Giữ ấm hộp ươm nhỏ bằng nhiệt đã tích từ trước.','Warms a small nursery box using previously stored heat.',
'Cần nạp ấm và giữ ẩm; rêu chết làm mạng trao nhiệt ngừng hoạt động.','Requires warmth to charge and moisture to live; dead moss stops the exchange.',
prop('Nhịp ấm trong đá','Warmth within Stone','Giải phóng dần phần nhiệt đã nhận vào vùng rễ còn sống.','Gradually releases received heat around its living roots.')),
('complex-can-lo-hoa-tuy',1,'Căn Lò Hỏa Tủy','Hearthmarrow Root','Rễ cây và than kết mạch dưới tro','A root and coal joined beneath ash',
'Người làm vườn chôn một rễ cây cháy dở trong hố than để mùa sau bón đất. Mùa sau chỉ còn tuyết; rễ ấy đã học cách hút hơi ấm từ than tắt và đưa lên những mắt mầm đỏ. Một nhánh khoáng hóa len vào từng thớ gỗ, còn nhựa cây phủ lấy những đường than như mạch máu mới.\n\nCăn Lò Hỏa Tủy được chuyển sang nhà ươm và trạm cứu thương. Nó trả nhiệt chậm, đều, đủ cho một chậu nước thôi đóng váng trong đêm. Những người chăm nó phải để lại phần nhựa và nước cần thiết, bởi buồng lửa này còn phải lớn lên.','A gardener buried a half-burned root in a charcoal pit for the following season’s soil. The following season brought only snow; the root had learned to draw warmth from spent coal and lift it into red buds. Mineral veins entered each wood-fibre while sap covered the coal-paths like new blood vessels.\n\nHearthmarrow Root passes into nurseries and aid stations. It returns heat slowly and steadily, enough to keep a basin from icing over at night. Its keepers must leave the sap and water it needs, for this furnace still has to grow.',
'Sưởi nhẹ nước và hộp ươm, dự trữ nhiệt cho đêm lạnh.','Gently warms water and nursery boxes and stores heat for cold nights.',
'Rễ bị cắt khỏi mạng than sẽ héo; nhiệt lượng giảm theo sức sống của nó.','A root severed from the coal network withers; output declines with its vitality.',
prop('Dẫn nhiệt qua nhựa','Sap-Borne Warmth','Đưa nhiệt đã tích dọc những nhánh rễ tới vùng cần sưởi.','Carries stored heat along root branches to the area requiring warmth.')),
('complex-to-ong-dong-lo',2,'Tổ Ong Đồng Lò','Bronze-Furnace Hive','Bầy ong sống trong cấu trúc đồng ghi hình khuôn','A living hive within pattern-retaining bronze',
'Một tổ ong trú trong chiếc khuôn đúc bỏ quên đã phủ sáp lên những hình trang trí còn nóng. Thế hệ nở ra sau mùa băng đầu tiên mang ánh đồng trên bụng, và mỗi ô sáp giữ được đường nét của vật từng đặt vào. Khi thợ đúc đưa một chốt thép vào tổ, sáng hôm sau ong đã xây chung quanh nó một khuôn rỗng chính xác.\n\nNgười ta bắt đầu nuôi tổ cạnh xưởng pháo. Mật dành cho bầy; phôi kim loại dành cho thợ. Giữa hai thứ ấy, một công xưởng tìm được cách nhớ hàng trăm hình dạng bằng sự kiên nhẫn của những cánh nhỏ.','A hive sheltered in an abandoned casting mould and waxed over its still-warm ornaments. The generation born after the first frozen season carried bronze upon its abdomens, and each wax cell retained the outline of objects placed within it. When a founder inserted a steel pin, the bees had built an exact hollow mould around it by morning.\n\nHives began to be kept beside gun foundries. Honey belongs to the swarm; metal blanks belong to the smith. Between them a workshop learns to remember hundreds of shapes through the patience of small wings.',
'Tạo khuôn sáp chính xác để đúc cấu kiện và sửa máy.','Makes precise wax moulds for casting components and repairing machinery.',
'Cần vật mẫu và thời gian làm tổ. Đầu độc bầy ong hoặc làm biến dạng khuôn sáp phá hỏng sản phẩm.','Requires a pattern object and nesting time. Poisoning the swarm or distorting the wax ruins the product.',
prop('Tổ nhớ hình','Pattern-Remembering Hive','Dựng ô sáp quanh vật mẫu, giữ khuôn sau khi lấy vật ra.','Builds wax cells around a pattern and preserves the mould after removal.')),
('complex-hac-loc-dia-mach',3,'Hắc Lộc Địa Mạch','Earthvein Black Stag','Hươu sống với mạng sừng khoáng nghe đường nước','A living stag with mineral antlers sensing watercourses',
'Con hươu được tìm thấy giữa một mỏ đã ngập, chân đặt trên bậc đá cuối cùng còn khô. Quặng đen mọc dọc sừng thành những nhánh giống dòng sông nhìn từ trời. Mỗi lần nó cúi đầu, vũng nước dưới chân đổi hướng về một khe đá khác.\n\nĐàn con về sau mang cùng vân khoáng, nhưng chỉ những cá thể sống lâu cùng một thung lũng mới học được đường nước của nơi ấy. Người dẫn đoàn trao muối, chờ nó tự đi trước và đưa dân qua những lòng sông đang ngủ dưới băng.','The stag was found in a flooded mine, standing upon the last dry step. Black ore grew along its antlers in branches resembling rivers seen from above. Each bow of its head turned the pool beneath it towards another crack.\n\nLater offspring carried the same mineral tracery, though only individuals long resident in one valley learned its waterways. Guides offer salt, wait for it to lead and carry refugees across rivers sleeping beneath the ice.',
'Tìm dòng nước ngầm và chọn lối vượt thung lũng phù hợp hành vi con vật.','Locates underground watercourses and guides valley crossings according to the animal’s behaviour.',
'Tri thức gắn với vùng nó đã sống. Ép buộc hoặc chuyển vùng đột ngột làm mất độ tin cậy của hành vi dẫn đường.','Its knowledge belongs to places it has inhabited. Coercion or abrupt relocation makes its guidance unreliable.',
prop('Nghe dòng dưới đá','Hear Water beneath Stone','Mạng khoáng trong sừng phản ứng với dòng nước ở địa hình quen thuộc.','The antlers’ mineral network responds to water moving through familiar terrain.')),
('complex-giap-vuon-bach-thiet',4,'Giáp Vườn Bạch Thiết','Whiteiron Garden Harness','Giáp kim loại kết với hệ rễ tái cấu trúc','A metal harness joined to a restructuring root system',
'Một áo giáp thủng nằm suốt mùa trong vườn thuốc bị bỏ lại. Rễ đi qua lỗ đạn, uống nước gỉ và học lấy hình của những chiếc đinh tán. Khi người chủ trở về, lớp thép đã khép kín quanh một nhịp sống mới.\n\nVườn Bạch Thiết phát triển trên người mang như một công trình được chăm từng ngày. Rễ bó những chỗ giáp nứt, mọc thành nẹp cho cánh tay bị thương, rồi trả lại khớp cử động khi người giữ giáp gọi đúng nhịp. Những chiến dịch dài để lại trên nó cả vết chém lẫn vòng sinh trưởng.','A pierced cuirass lay all season in an abandoned medicinal garden. Roots passed through bullet-holes, drank rust-water and learned the shape of rivets. When its owner returned, steel had closed around a new pulse of life.\n\nThe Whiteiron Garden grows upon its bearer like a structure tended daily. Roots bind fractured plates, form splints around an injured arm and restore joint movement when its keeper calls the proper rhythm. Long campaigns leave both blade-marks and growth rings upon it.',
'Bảo hộ, tự vá cấu kiện giáp và tạo nẹp trợ lực quanh chi bị thương.','Provides protection, repairs armour components and forms supporting splints around injured limbs.',
'Cần nước, khoáng và thời gian. Rễ mọc sai do chăm sóc cẩu thả có thể khóa cứng khớp người mang.','Requires water, minerals and time. Neglected growth can lock the bearer’s joints.',
prop('Vá giáp bằng rễ','Root-Woven Repair','Đưa rễ khoáng hóa qua vết hỏng để giằng lại các phần giáp còn nền bám.','Threads mineralised roots through damage to brace armour portions with remaining anchor surfaces.')),
('complex-ca-voi-lo-tham',5,'Cá Voi Lò Thẳm','Abyssal Furnace Whale','Sinh vật biển cộng sinh với khoáng nhiệt trong xương','A sea creature symbiotic with thermal minerals in its bones',
'Bộ xương của nó từng thuộc một con cá voi chết dưới bãi tàu săn. Nhiều năm sau, những khối khoáng sinh nhiệt kết vào tủy và đàn sinh vật nhỏ trú trong đó đã dựng lại quanh xương một cơ thể biết bơi. Hơi nước nổi trên đường nó đi, còn băng khép sau đuôi thành những phiến mỏng có thể tách bằng mái chèo.\n\nCá Voi Lò Thẳm đi theo những tiếng hát có nhịp của loài cũ. Một đoàn tàu được nó chấp nhận có thể theo hành lang nước ấm qua biển đóng. Những thủy thủ cẩn trọng thả thức ăn từ xa, giữ lửa pháo tắt và để con đường ấy được mở bởi ý muốn của một sinh vật.','Its skeleton once belonged to a whale killed beneath a hunting station. Years later heat-bearing minerals gathered in the marrow, and small creatures sheltering there built a swimming body around the bones. Vapour rises along its course while ice closes behind its tail in sheets an oar can part.\n\nThe Abyssal Furnace Whale follows measured songs resembling those of its former kind. A convoy it accepts can follow its warm-water corridor through a frozen sea. Careful sailors offer food at a distance, keep their gun-fires cold and allow the route to open by a creature’s choice.',
'Mở hành lang nước qua băng và dẫn đoàn tàu theo đường di cư.','Opens water corridors through ice and guides convoys along its migration.',
'Lộ trình và phản ứng thuộc về sinh vật. Sợ hãi hoặc bị săn đuổi có thể khiến nó lặn xuống, để tàu lại giữa băng đang khép.','Its route and responses belong to the creature. Fear or pursuit can make it dive, leaving ships amid closing ice.',
prop('Hành lang lò thẳm','Abyssal Furnace Passage','Trao nhiệt dọc đường bơi để phá cấu trúc băng phía trước và giữ một khoảng nước cho đoàn theo sau.','Releases heat along its swimming path to break ice ahead and preserve a water interval for following vessels.')),
('complex-vuon-trong-tieng-chuong',6,'Vườn Trong Tiếng Chuông','Garden within a Bell’s Voice','Miền thực vật tồn tại trong âm chuông và hạt khoáng','A botanical domain existing within bell-sound and mineral seeds',
'Người giữ vườn chôn cả mùa xuân cuối cùng vào một chuông đồng: hạt giống, đất ấm và tên của những người đã cùng trồng. Sau nhiều năm bị tuyết lấp, chiếc chuông được kéo lên; mỗi lần ngân, người đứng gần nghe mùi lá non trước khi thấy đường viền khu vườn mở trong không khí.\n\nHạt khoáng là những chiếc neo của miền ấy. Khi được đặt quanh nền đất thật, chúng cho phép tiếng chuông trao một mùa sinh trưởng vào thời gian giữa hai nhịp. Cây lớn lên trong khoảng ấy mang được quả ra ngoài. Những người giữ chuông học cách đếm cả tên người lẫn hạt giống, vì khu vườn chỉ mở những luống còn được nhớ cùng nhau.','A gardener buried a final spring within a bronze bell: seeds, warm earth and the names of those who had planted beside him. Years beneath the snow passed before it was raised; with each peal, nearby listeners smelled young leaves before the outline of a garden opened in the air.\n\nMineral seeds anchor the domain. Placed around real soil, they let the peal grant a growing season within the time between two beats. Plants raised there can carry fruit outside. Keepers learn to count names as carefully as seeds, for the garden opens only beds still remembered together.',
'Dựng miền canh tác tạm thời có mùa sinh trưởng riêng, đưa sản vật ra thế giới ngoài.','Raises a temporary cultivation domain with its own growing season and carries produce into the outer world.',
'Cần neo hạt, đất thật và ký ức chung về người từng gieo. Mất nhịp chuông làm miền khép; người bên trong phải theo lối neo trở ra.','Requires seed-anchors, real soil and shared remembrance of former planters. A broken peal closes the domain; those within must return through its anchors.',
prop('Mùa giữa hai nhịp','A Season between Two Beats','Mở khoảng sinh trưởng cho luống đã được neo và gọi tên trong hồi chuông.','Opens a growing interval for a bed anchored and named within the peal.')),
('complex-cot-buom-muoi-ba',7,'Cột Buồm Thứ Mười Ba','The Thirteenth Mast','Tàu gỗ sống, thuyền trưởng ký ức và hải trình chưa thành','A living wooden ship, a remembered captain and an unrealised voyage',
'Bản thiết kế chỉ có mười hai cột buồm. Khi con tàu đầu tiên chết giữa biển băng, thợ cả trên bờ vẫn tiếp tục đóng phần chưa kịp hoàn thành, và mỗi đinh ông đóng biến mất khỏi xưởng trong đêm. Ngoài khơi, xác tàu dựng lên cột thứ mười ba. Gỗ mọc từ ký ức công việc, buồm nhận gió của những hải trình từng được hứa, còn bóng thuyền trưởng bước trở lại trên boong bằng tiếng gọi của thủy thủ sống sót.\n\nCon tàu có thể tới một bến chưa từng được xây nếu có người thật đang chờ ở nơi bến ấy đáng lẽ thành hình. Nó mở hải trình qua những phần đời bị lịch sử bỏ dở, mang người sống đi trên một lời hẹn còn hiệu lực. Mỗi lần cập bến, một con đường khả hữu khép vĩnh viễn phía sau: tương lai đã cho nó gió nay chỉ còn thuộc về hành trình vừa chọn.','The plans held only twelve masts. When the first ship died in pack ice, its master-builder ashore kept making the unfinished portions, and every nail vanished from his workshop overnight. Offshore, the wreck raised a thirteenth mast. Wood grew from remembered labour, sails received the winds of promised voyages and a captain’s shadow returned to the deck through the calls of surviving sailors.\n\nThe ship can reach a harbour never built if a living person waits where that harbour should have stood. It sails through lives left unfinished by history, carrying the living upon a promise still in force. At each landfall, a possible route closes forever behind it: the future that lent its wind now belongs only to the voyage chosen.',
'Vượt biển qua hải trình khả hữu để tới nơi có người sống thực sự đang chờ.','Crosses possible sea-routes to reach a place where a living person is truly waiting.',
'Cần lời hẹn có người nhận và vị trí có thể gọi tên. Mỗi chuyến tiêu một hải trình khả hữu; những lối đã khép không được gọi lại bằng cùng lời hẹn.','Requires a promise with a recipient and a place that can be named. Each voyage spends a possible route; closed paths cannot be recalled through the same promise.',
prop('Hải trình chưa thành','The Unrealised Voyage','Theo gió từ một tuyến đường khả hữu đến nơi chờ được xác định bằng lời hẹn sống.','Follows wind from a possible route to a waiting-place defined by a living promise.')),
]
for id,rank,nv,ne,fv,fe,lv,le,uv,ue,limv,lime,skill in complexes:
 m=put(id,'complex',rank,nv,ne,fv,fe,lv,le,uv,ue,limv,lime,[skill],[prop('Nhiều bản chất cùng tồn tại','Coexisting Natures','Các thành phần sống, vật chất hoặc miền hiện tượng vận hành như một tổ hợp; tách chúng làm thay đổi cơ chế của hiện vật.','Living, material or phenomenal constituents operate as one complex; separating them changes its workings.')],editorial=True)
 quantity(m,'unknown',None,'Chưa có khảo sát đủ để xác nhận số lượng còn tồn tại.','No sufficient survey has established the surviving quantity.')

# Catalogue-wide structure: preserve former uses as applications, rather than
# forcing exponentially many skills. Original prose remains traceable in git.
for a in data.values():
 for m in a:
  if 'quantity' not in m:quantity(m)
  for s in m['sources']:
   actual=tabs[str(s['volume'])].get(s['tab_id'])
   if actual:s['chapter']=actual['chapter']
  for k in ['name_vi','name_en','form_vi','form_en','rarity_note_vi','rarity_note_en','lore_vi','lore_en','use_vi','use_en','limits_vi','limits_en','behavior_vi','behavior_en']:
   if k in m:m[k]=m[k].replace(' — ','. ').replace(' – ','; ').replace('1–100','1 đến 100' if k.endswith('_vi') else '1 to 100')
  if len(m['skills'])>m['rarity']+1:
   old=m['skills'];m['applications']=old
   m['skills']=[prop('Cơ chế chủ đạo','Core Working',m['use_vi'],m['use_en'])]
   m['content_revision']='catalogue-v3'
  if m.get('content_revision')=='genesis-v2':m['content_revision']='catalogue-v3'
  # The collection's rarity-7 label does not establish singleton quantity.
  m.setdefault('applications',[])

for g,a in data.items():(root/f'{g}.json').write_text(json.dumps(a,ensure_ascii=False,indent=2)+'\n')
summary={'revision':'guard-v3','records':sum(map(len,data.values())),'guard_creations':sum(m.get('royal_guard',{}).get('relation')=='deployment' for a in data.values() for m in a),'complexes':len(data['complex']),'rule':'Power tier and abundance are independent. Skill counts are caps, not quotas. Existing variants retained as applications.','artwork_generated':0}
(root/'editorial/guard-v3/progress.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2)+'\n')
print(json.dumps(summary))
